289: pub(crate) fn resolution_scale<const L: usize>(
290:     layout: &[QuantityMeta],
291:     e_rows: &[Option<Wide<L>>],
292:     bodies: usize,
293: ) -> Result<Vec<[f64; 2]>, AttemptStop>
294: where
295:     Wide<L>: SupportedWidth,
296: {
297:     let mut top = vec![[Wide::<L>::ZERO; 2]; bodies];
298:     for (meta, e) in layout.iter().zip(e_rows) {
299:         let (Some(e), Some(slot)) = (
300:             e,
301:             match meta.kind {
302:                 Kind::Force => Some(0usize),
303:                 Kind::Moment => Some(1),
304:                 _ => None,
305:             },
306:         ) else {
307:             continue;
308:         };
309:         let current = &mut top[meta.body as usize][slot];
310:         if e.cmp_value(current) == CmpOrdering::Greater {
311:             *current = *e;
312:         }
313:     }
314:     top.iter()
315:         .map(|[fo, mo]| Ok([binary64_up(fo)?, binary64_up(mo)?]))
316:         .collect()
317: }

